package com.solarmind.repository; import com.solarmind.entity.Location; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface LocationRepository extends JpaRepository<Location,Long>{Optional<Location> findByCityAndDistrictAndStateAndLatitudeAndLongitude(String city,String district,String state,Double latitude,Double longitude); @Query("select l from Location l where lower(l.city) like lower(concat('%',:q,'%')) or lower(l.district) like lower(concat('%',:q,'%')) or lower(l.state) like lower(concat('%',:q,'%')) order by l.city") List<Location> search(@Param("q") String query, org.springframework.data.domain.Pageable pageable);}
